nextflow_process {

    name "Test Process SENTIEON_RSEMCALCULATEEXPRESSION"
    script "../main.nf"
    process "SENTIEON_RSEMCALCULATEEXPRESSION"
    tag "modules"
    tag "modules_nfcore"
    tag "sentieon"
    tag "sentieon/rsemcalculateexpression"
    tag "sentieon/rsempreparereference"


    test("homo_sapiens - bam") {

        setup {
            run("SENTIEON_RSEMPREPAREREFERENCE") {
                script "../../../sentieon/rsempreparereference/main.nf"
                process {
                    """
                    input[0] = Channel.of(file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true))
                    input[1] = Channel.of(file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.gtf', checkIfExists: true))
                    """
                }
            }
        }

        when {
            params {
                outdir = "$outputDir"
            }
            process {
                """
                input[0] = Channel.of([
                    [ id:'test', strandedness: 'forward' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/rsem.transcript.bam', checkIfExists: true)
                ])
                input[1] = SENTIEON_RSEMPREPAREREFERENCE.out.index
                """
            }
        }
        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    process.out.counts_gene,
                    process.out.counts_transcript,
                    process.out.stat,
                    process.out.findAll { key, val -> key.startsWith("versions") }
                ).match() }
            )
        }
    }

    test("homo_sapiens - fastq") {

        config "./nextflow.config"

        setup {
            run("SENTIEON_RSEMPREPAREREFERENCE") {
                script "../../../sentieon/rsempreparereference/main.nf"
                process {
                    """
                    input[0] = Channel.of(file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true))
                    input[1] = Channel.of(file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.gtf', checkIfExists: true))
                    """
                }
            }
        }

        when {
            params {
                outdir = "$outputDir"
            }
            process {
                """
                input[0] = Channel.of([
                    [ id:'test', strandedness: 'forward' ], // meta map
                    [
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/fastq/test_rnaseq_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/fastq/test_rnaseq_2.fastq.gz', checkIfExists: true)
                    ]
                ])
                input[1] = SENTIEON_RSEMPREPAREREFERENCE.out.index
                """
            }
        }
        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    process.out.counts_gene,
                    process.out.counts_transcript,
                    process.out.stat,
                    process.out.findAll { key, val -> key.startsWith("versions") }
                ).match() },
                { assert path(process.out.logs.get(0).get(1)).exists() }
            )
        }
    }

    test("homo_sapiens - stub") {

        config "./nextflow.config"

        options "-stub"

        setup {
            run("SENTIEON_RSEMPREPAREREFERENCE") {
                script "../../../sentieon/rsempreparereference/main.nf"
                process {
                    """
                    input[0] = Channel.of(file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true))
                    input[1] = Channel.of(file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.gtf', checkIfExists: true))
                    """
                }
            }
        }

        when {
            process {
                """
                input[0] = Channel.of([
                    [ id:'test', strandedness: 'forward' ], // meta map
                    [
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/fastq/test_rnaseq_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/fastq/test_rnaseq_2.fastq.gz', checkIfExists: true)
                    ]
                ])
                input[1] = SENTIEON_RSEMPREPAREREFERENCE.out.index
                """
            }
        }
        then {
            assertAll(
                { assert process.success },
                { assert path(process.out.counts_gene.get(0).get(1)).exists() },
                { assert path(process.out.counts_transcript.get(0).get(1)).exists() },
                { assert path(process.out.stat.get(0).get(1)).exists() },
                { assert path(process.out.logs.get(0).get(1)).exists() },
                { assert snapshot(
                    process.out.findAll { key, val -> key.startsWith("versions") }
                ).match() }
            )
        }
    }
}

process {

    withName: SENTIEON_RSEMPREPAREREFERENCE {
        ext.args = '--star'
    }

    withName: SENTIEON_RSEMCALCULATEEXPRESSION {
        ext.args = '--star --star-gzipped-read-file'
    }

}

env {
    // NOTE This is how pipeline users will use Sentieon in real world use
    // TODO: Update to `env('SENTIEON_LICSRVR_IP')` when minimum Nextflow version is >= 26.04.0
    SENTIEON_LICENSE = env('SENTIEON_LICSRVR_IP')
    // NOTE This should only happen in GitHub actions or nf-core MegaTests
    // TODO: Update to `env('SENTIEON_AUTH_MECH')` when minimum Nextflow version is >= 26.04.0
    SENTIEON_AUTH_MECH = env('SENTIEON_AUTH_MECH')
    SENTIEON_AUTH_DATA = secrets.SENTIEON_AUTH_DATA
    // NOTE This is how pipeline users will test out Sentieon with a license file
    // nextflow secrets set SENTIEON_LICENSE_BASE64 \$(cat <sentieon_license_file.lic> | base64 -w 0)
}
